#!/usr/bin/env bash
#
# Description: Makes <dir>/hyprland.lua axiom's for the "managed" Hyprland
#              mode (HyprlandConfigManager), says what that would do, or
#              gives it back when axiom leaves that mode.
# Usage:       claim_hyprland.sh check <dir> <header> [<fallback>]
#              claim_hyprland.sh claim <dir> <header> [<fallback>]
#              claim_hyprland.sh release <dir> <header> <fallback>
#              header: the first line prefix of a file axiom wrote
#              ("-- Generated by axiom"); fallback: the hyprland.lua release
#              writes when nothing was set aside. Prints one word:
#                ours     the file is already axiom's
#                blocked:link       <dir> or its hyprland.lua is a symlink
#                blocked:git:<repo> <dir> is in the git repository <repo>
#                         either way never taken over
#                adopt    (check) an existing hyprland.lua would be moved
#                stock    (check) hyprland.lua is Hyprland's example config
#                         ($AXIOM_HYPR_EXAMPLE, /usr/share/hypr/hyprland.lua),
#                         as is or as Hyprland autogenerates it, maybe with
#                         the autostart line install.sh adds:
#                         it would only be backed up, since its binds and
#                         monitor rule would fight axiom's
#                released (check) hyprland.lua is <fallback>, as release
#                         wrote it (with or without the lines that load the
#                         included module): it would be replaced, with no
#                         backup, since it holds nothing of the user's and
#                         the managed one starts axiom and loads user/ itself
#                new      (check) there's no hyprland.lua yet
#                adopted:<name>  (claim) done: user/ exists, and the
#                         existing hyprland.lua is copied to user/<name>
#                         (00-previous.lua, or 00-previous-<date>.lua when
#                         that's taken), with a dated copy beside the
#                         original path. Its lines that start axiom or load
#                         its included module are commented out: axiom's
#                         hyprland.lua does both now, and a second start
#                         without -n would be a second shell
#                created  (claim) done: user/ exists; there was no
#                         hyprland.lua
#                replaced (claim) done: user/ exists, and the example
#                         config is only kept as the dated copy (<fallback>
#                         isn't kept)
#              claim leaves hyprland.lua where it is, for the managed one to
#              replace (an atomic write): Hyprland reloads when the file
#              changes, and must never find it missing. A claim of the same
#              file again (that write never came) reuses its copies.
#              Writes nothing on check, ours or blocked.
#              release prints one word too:
#                notours  hyprland.lua isn't axiom's (or is missing):
#                         nothing to give back, nothing written
#                blocked:link, blocked:git:<repo>  as above, nothing written
#                restored:<from>:<n>  done: hyprland.lua is what claim set
#                         aside again: <from> is user/<name> (the newest
#                         adopted 00-previous*.lua, moved back with the
#                         lines claim commented out restored) or else the
#                         newest hyprland.lua.axiom-backup-* (Hyprland's
#                         example config); <n> files in user/*.lua it
#                         doesn't load (0 when it loads them)
#                written  done: nothing was set aside, so hyprland.lua is
#                         <fallback> (a file of the user's that loads
#                         user/*.lua)

set -uo pipefail

action=${1:-}
dir=${2:-}
header=${3:-}
example=${AXIOM_HYPR_EXAMPLE:-/usr/share/hypr/hyprland.lua}
fallback=${4:-}
if [[ "$action" != "check" && "$action" != "claim" && "$action" != "release" ]] || [[ -z "$dir" || -z "$header" ]] ||
  [[ "$action" == "release" && -z "$fallback" ]]; then
  echo "Usage: $0 check|claim <dir> <header> [<fallback>] | release <dir> <header> <fallback>" >&2
  exit 2
fi
dir=${dir%/}
file=$dir/hyprland.lua

is_ours() {
  [[ -f "$file" ]] && [[ "$(head -n 1 "$file")" == "$header"* ]]
}
if [[ "$action" == "release" ]]; then
  if ! is_ours; then
    echo notours
    exit 0
  fi
elif is_ours; then
  echo ours
  exit 0
fi
if [[ -L "$dir" || -L "$file" ]]; then
  echo blocked:link
  exit 0
fi
if repo=$(git -C "$dir" rev-parse --show-toplevel 2>/dev/null); then
  echo "blocked:git:$repo"
  exit 0
fi

# The example config, give or take whitespace, blank lines and the line
# that starts axiom (install.sh's, marked "-- axiom"). A config Hyprland
# generated itself (with no hyprland.lua at its first start) is the example
# too: it adds a banner and an `autogenerated` line, and picks the `menu`
# launcher by what's installed
stock_lines() {
  grep -vE '(qs|quickshell) .*axiom.*-- axiom[[:space:]]*$|^-- (-- )+--[[:space:]]*$|^-- AUTOGENERATED HYPRLAND CONFIG\.|^-- EDIT THIS CONFIG ACCORDING TO THE WIKI|^hl\.config\(\{ *autogenerated *= *true *\}\)|^local menu +=' "$1"
}
is_stock() {
  [[ -f "$example" ]] && diff -qbB <(stock_lines "$file") <(stock_lines "$example") >/dev/null 2>&1
}
# The file release writes, give or take whitespace, blank lines and the
# lines that load the included module (it has them when written for that
# mode): an edited one is the user's, and is adopted
released_lines() {
  grep -vE 'pcall\(dofile, .*axiom/hyprland\.lua|^if ok then axiom\.setup\(\) end' "$1"
}
is_released() {
  [[ -n "$fallback" ]] && diff -qbB <(released_lines "$file") <(printf '%s\n' "$fallback" | released_lines /dev/stdin) >/dev/null 2>&1
}

# Comments out the lines that start axiom (install.sh's, the Hyprland
# page's, any `qs … -c axiom`) or load its included module, unless that
# leaves the file unparsable (then it stays as it is)
disable_axiom_lines() {
  local target=$1 edited
  edited=$(mktemp) || return 0
  sed -E \
    -e '/^[[:space:]]*--/b' \
    -e '/(qs|quickshell) .*(-c +['"'"'"]?axiom|-p +['"'"'"]?[^[:space:]]*axiom)|dofile.*axiom\/hyprland\.lua|axiom\.setup\(/s/^/-- (axiom starts and loads itself now) /' \
    "$target" >"$edited"
  if luac -p "$edited" >/dev/null 2>&1; then
    cat "$edited" >"$target"
  fi
  rm -f "$edited"
}

# Undoes disable_axiom_lines in a copy of <file> at <target>, unless that
# leaves it unparsable (then the copy keeps them commented out)
enable_axiom_lines() {
  local source=$1 target=$2
  sed -E 's/^-- \(axiom starts and loads itself now\) //' "$source" >"$target" || return 1
  if ! luac -p "$target" >/dev/null 2>&1; then
    cat "$source" >"$target"
  fi
}

# The newest adopted config in user/ (00-previous.lua is the first,
# 00-previous-<date>.lua the later ones) and the newest dated backup
newest_previous() {
  local dated
  dated=$(find -H "$dir/user" -maxdepth 1 -name '00-previous-*.lua' -printf '%f\n' 2>/dev/null | sort | tail -n 1)
  if [[ -n "$dated" ]]; then
    echo "$dated"
  elif [[ -f "$dir/user/00-previous.lua" ]]; then
    echo 00-previous.lua
  fi
}
newest_backup() {
  find "$dir" -maxdepth 1 -name 'hyprland.lua.axiom-backup-*' -printf '%f\n' 2>/dev/null | sort | tail -n 1
}

if [[ "$action" == "release" ]]; then
  # The newest of what claim set aside: an adopted config, else the backup
  # of the example config it replaced
  previous=$(newest_previous)
  backup=$(newest_backup)
  staged=$(mktemp "$dir/.hyprland.lua.XXXXXX") || exit 1
  trap 'rm -f "$staged"' EXIT
  if [[ -n "$previous" ]]; then
    enable_axiom_lines "$dir/user/$previous" "$staged" && chmod --reference="$dir/user/$previous" "$staged" &&
      mv "$staged" "$file" && rm -f "$dir/user/$previous" || exit 1
    from=user/$previous
  elif [[ -n "$backup" ]]; then
    mv "$dir/$backup" "$file" || exit 1
    from=$backup
  else
    printf '%s\n' "$fallback" >"$staged" && chmod 644 "$staged" && mv "$staged" "$file" || exit 1
    echo written
    exit 0
  fi
  # (none when it loads them itself: a file release once wrote)
  left=0
  grep -q 'pcall(require, "user\.' "$file" ||
    left=$(find -H "$dir/user" -maxdepth 1 -name '*.lua' 2>/dev/null | wc -l)
  echo "restored:$from:$left"
  exit 0
fi

if [[ "$action" == "check" ]]; then
  if [[ ! -f "$file" ]]; then
    echo new
  elif is_stock; then
    echo stock
  elif is_released; then
    echo released
  else
    echo adopt
  fi
  exit 0
fi

mkdir -p "$dir/user" || exit 1
if [[ -f "$file" ]]; then
  backup="$file.axiom-backup-$(date +%Y%m%d-%H%M%S)"
  if is_released; then
    echo replaced
    exit 0
  fi
  # Already copied by a claim whose managed write never came
  last=$(newest_backup)
  if [[ -n "$last" ]] && cmp -s "$file" "$dir/$last"; then
    previous=$(newest_previous)
    if is_stock; then
      echo replaced
      exit 0
    elif [[ -n "$previous" ]]; then
      echo "adopted:$previous"
      exit 0
    fi
  fi
  if is_stock; then
    cp -p "$file" "$backup" || exit 1
    echo replaced
    exit 0
  fi
  name=00-previous.lua
  [[ -e "$dir/user/$name" ]] && name=00-previous-$(date +%Y%m%d-%H%M%S).lua
  cp -p "$file" "$backup" && cp -p "$file" "$dir/user/$name" || exit 1
  disable_axiom_lines "$dir/user/$name"
  echo "adopted:$name"
  exit 0
fi
echo created
